<template>
  <div class="space-y-8">
    <!-- Hero Section com Busca -->
    <div class="bg-gradient-to-r from-red-600 to-red-500 text-white rounded-2xl p-8 shadow-lg">
      <h1 class="text-4xl font-bold mb-2">Bem-vindo ao AiLarica</h1>
      <p class="text-red-100 mb-6">Descubra os melhores restaurantes e pratos perto de você</p>
      
      <!-- Barra de Busca -->
      <div class="relative">
        <input
          type="text"
          v-model="searchQuery"
          @input="handleSearch"
          placeholder="Buscar restaurantes ou pratos..."
          class="w-full px-6 py-4 rounded-full text-gray-800 focus:outline-none focus:ring-4 focus:ring-red-300 shadow-lg"
        />
        <svg class="absolute right-4 top-1/2 transform -translate-y-1/2 w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
        </svg>
      </div>
    </div>

    <!-- Filtros e Ordenação -->
    <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
      <div>
        <h2 class="text-2xl font-bold text-gray-900">Restaurantes Próximos</h2>
        <p class="text-gray-600 text-sm mt-1">{{ restaurants.length }} restaurantes disponíveis</p>
      </div>
      
      <div class="flex gap-2">
        <button
          @click="sortBy = 'rating'"
          :class="[
            'px-4 py-2 rounded-lg font-medium transition-all',
            sortBy === 'rating'
              ? 'bg-red-600 text-white shadow-md'
              : 'bg-white text-gray-700 border border-gray-300 hover:border-red-600'
          ]"
        >
          ⭐ Melhor Avaliado
        </button>
        <button
          @click="sortBy = 'delivery'"
          :class="[
            'px-4 py-2 rounded-lg font-medium transition-all',
            sortBy === 'delivery'
              ? 'bg-red-600 text-white shadow-md'
              : 'bg-white text-gray-700 border border-gray-300 hover:border-red-600'
          ]"
        >
          🚗 Mais Rápido
        </button>
      </div>
    </div>

    <!-- Grid de Restaurantes -->
    <div v-if="restaurants.length > 0" class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
      <div
        v-for="restaurant in sortedRestaurants"
        :key="restaurant.id"
        class="bg-white rounded-2xl shadow-md hover:shadow-2xl transition-all duration-300 overflow-hidden cursor-pointer transform hover:scale-105"
        @click="goToRestaurant(restaurant.id)"
      >
        <!-- Imagem do Restaurante -->
        <div class="relative h-48 overflow-hidden bg-gradient-to-br from-red-100 to-red-50">
          <img
            :src="restaurant.image"
            alt="Imagem do Restaurante"
            class="w-full h-full object-cover"
          />
          <!-- Badge de Avaliação -->
          <div class="absolute top-4 right-4 bg-white rounded-full px-3 py-1 shadow-lg flex items-center space-x-1">
            <span class="text-yellow-500 font-bold">★</span>
            <span class="font-bold text-gray-800">{{ restaurant.rating }}</span>
          </div>
          <!-- Badge de Status -->
          <div class="absolute top-4 left-4 bg-green-500 text-white px-3 py-1 rounded-full text-xs font-bold">
            Aberto
          </div>
        </div>

        <!-- Conteúdo do Restaurante -->
        <div class="p-5">
          <!-- Nome e Categoria -->
          <h3 class="text-xl font-bold text-gray-900 mb-1">{{ restaurant.name }}</h3>
          <p class="text-sm text-gray-600 mb-3">{{ restaurant.category }}</p>

          <!-- Avaliações e Reviews -->
          <div class="flex items-center text-sm text-gray-600 mb-4">
            <span class="text-gray-500">({{ restaurant.reviews }} avaliações)</span>
          </div>

          <!-- Informações de Entrega -->
          <div class="flex items-center justify-between pt-4 border-t border-gray-200">
            <div class="flex items-center space-x-2 text-sm text-gray-700">
              <svg class="w-4 h-4 text-red-600" fill="currentColor" viewBox="0 0 20 20">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5.951-1.488 5.951 1.488a1 1 0 001.169-1.409l-7-14z"></path>
              </svg>
              <span>{{ restaurant.deliveryTime }} min</span>
            </div>
            <div class="flex items-center space-x-2 text-sm text-gray-700">
              <svg class="w-4 h-4 text-red-600" fill="currentColor" viewBox="0 0 20 20">
                <path d="M8.16 5a.5.5 0 00-.496.545l.002.02.001.011.002.01.002.015.001.009.002.013.001.01.002.014.001.009.002.012.001.011.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.013.001.01.002.012.001.01.002.013.001.009.002.01